class Solution {
public:
    int minCostToEqualizeArray(vector<int>& nums, int cost1, int cost2) {
        long long MOD = 1e9 + 7;
        int n = nums.size();
        long long max_val = *max_element(nums.begin(), nums.end());
        long long min_val = *min_element(nums.begin(), nums.end());

        long long total_diff = 0;
        for (int x : nums) total_diff += (max_val - x);

        if (2LL * cost1 <= cost2 || n <= 2) {
            return (total_diff * cost1) % MOD;
        }

        long long ans = -1;

        for (long long target = max_val; target <= 2 * max_val; ++target) {
            long long total_ops = total_diff + (target - max_val) * n;
            long long max_ops = target - min_val;
            long long rem_ops = total_ops - max_ops;
            long long cost = 0;
            if (max_ops <= rem_ops) {
                long long pairs = total_ops / 2;
                long long singles = total_ops % 2;
                cost = pairs * cost2 + singles * cost1;
            } else {
                long long pairs = rem_ops;
                long long singles = max_ops - rem_ops;
                cost = pairs * cost2 + singles * cost1;
            }
            if (ans == -1 || cost < ans) {
                ans = cost;
            } else if (cost > ans + 2 * (target - max_val) * cost1) {
                break;
            }
        }

        return ans % MOD;
    }
};

