        long MOD = 1_000_000_007L;
        int n = nums.length;
        long maxVal = 0, minVal = Long.MAX_VALUE;
        for (int x : nums) {
            if (x > maxVal) maxVal = x;
            if (x < minVal) minVal = x;
        }

        long totalDiff = 0;
        for (int x : nums) totalDiff += (maxVal - x);

        if (2L * cost1 <= cost2 || n <= 2) {
            return (int) ((totalDiff % MOD * cost1) % MOD);
        }

        long ans = -1;

        for (long target = maxVal; target <= 2 * maxVal; target++) {
