var minCostToEqualizeArray = function(nums, cost1, cost2) {
    const MOD = 1000000007n;
    const n = BigInt(nums.length);
    let maxVal = 0n, minVal = BigInt(Infinity);
    let totalDiff = 0n;

    for (const x of nums) {
        const bx = BigInt(x);
        if (bx > maxVal) maxVal = bx;
        if (bx < minVal) minVal = bx;
    }
    for (const x of nums) totalDiff += (maxVal - BigInt(x));

    const c1 = BigInt(cost1), c2 = BigInt(cost2);
    if (2n * c1 <= c2 || n <= 2n) {
        return Number((totalDiff * c1) % MOD);
    }

    let ans = -1n;
    for (let target = maxVal; target <= 2n * maxVal; target++) {
        const totalOps = totalDiff + (target - maxVal) * n;
        const maxOps = target - minVal;
        const remOps = totalOps - maxOps;
        let cost = 0n;
        if (maxOps <= remOps) {
            const pairs = totalOps / 2n;
            const singles = totalOps % 2n;
            cost = pairs * c2 + singles * c1;
        } else {
            const pairs = remOps;
            const singles = maxOps - remOps;
            cost = pairs * c2 + singles * c1;
        }
        if (ans === -1n || cost < ans) {
            ans = cost;
        } else if (cost > ans + 2n * (target - maxVal) * c1) {
            break;
        }
    }

    return Number(ans % MOD);
};
